-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ich als IT-Systemkaufmann direkt Hardware für Kunden bestellen?', 2, '[{"text": "Ja", "correct": true, "because": "Beschaffung gehört dazu"}, {"text": "Nein", "correct": false, "because": "Teil der Aufgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein IT-Systemkaufmann auch programmieren können?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Beratung und Verkauf"}, {"text": "Ja", "correct": false, "because": "Technisches Verständnis reicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Kundenberatung eine Hauptaufgabe für IT-Systemkaufleute?', 2, '[{"text": "Ja", "correct": true, "because": "Kern der Rolle"}, {"text": "Nein", "correct": false, "because": "Beratung ist zentral"}]'),
